const rijen = $input.all().map(i => i.json).filter(r => r && r.tekst);
if (!rijen.length) {
  return [{ json: { resultaat: 'Er staan nog geen herinneringen ingesteld.' } }];
}
rijen.sort((a, b) => String(a.volgende_op).localeCompare(String(b.volgende_op)));
const regels = rijen.map(r => {
  const spec = parseSpec(r.herhaling);
  const dt = naarDt(r.volgende_op);
  let regel = '• ' + r.tekst + ' — ' + omschrijf(spec, dt);
  if (spec && dt) regel += ' (eerstvolgend: ' + dt.toFormat('dd-MM') + ')';
  return regel;
});
return [{ json: { resultaat: `Ingestelde herinneringen:\n${regels.join('\n')}` } }];

const invoer = $('Normaliseren').first().json;
const rijen = $input.all().map(i => i.json).filter(r => r && r.tekst);
const gezocht = invoer.tekst.toLowerCase();
if (!gezocht) {
  return [{ json: { id: '', geenMatch: true, melding: 'Geef aan welke herinnering verwijderd moet worden.' } }];
}
const matches = rijen.filter(r => {
  const t = String(r.tekst).toLowerCase();
  return t.includes(gezocht) || gezocht.includes(t);
});
if (!matches.length) {
  return [{ json: { id: '', geenMatch: true, melding: `Geen herinnering gevonden die lijkt op '${invoer.tekst}'.` } }];
}
return matches.map(r => ({ json: { id: r.id, tekst: r.tekst } }));

const gevonden = $('Zoek herinnering').all().map(i => i.json);
if (gevonden.length && gevonden[0].geenMatch) {
  return [{ json: { resultaat: gevonden[0].melding } }];
}
const namen = gevonden.map(g => g.tekst);
return [{ json: { resultaat: `Verwijderd: ${namen.join(', ')}` } }];
